const crypto = require('crypto');
const item = $input.first().json;

const token = $vars.TWILIO_AUTH_TOKEN;
const signature = item.headers?.['x-twilio-signature'] || '';
// ASSUMPTION — verify: webhookUrl is the exact URL Twilio called. It showed
// /webhook-test/... on your test capture; confirm it shows /webhook/... in a
// production execution before trusting it live.
const url = item.webhookUrl;
const params = item.body || {};

let valid = false;
let reason = null;

if (!token) reason = 'missing_auth_token';
else if (!signature) reason = 'missing_signature_header';
else if (!url) reason = 'missing_webhook_url';
else {
  // Twilio's documented algorithm: URL + each POST param (sorted by key) as key+value,
  // HMAC-SHA1 with the auth token, base64.
  // UNVERIFIED in n8n: sort order and body parsing are confirmed only if this returns true.
  let data = url;
  for (const key of Object.keys(params).sort()) data += key + params[key];
  const expected = crypto.createHmac('sha1', token).update(data, 'utf8').digest('base64');
  const a = Buffer.from(signature);
  const b = Buffer.from(expected);
  valid = a.length === b.length && crypto.timingSafeEqual(a, b);
  if (!valid) reason = 'signature_mismatch';
}

// Pass the original item through so later nodes can still read headers/body.
return [{ json: { ...item, signature_valid: valid, signature_reason: reason } }];

// Field paths verified from your real Twilio payload on 2026-10-20.
const b = $('Verify Twilio signature').first().json.body || {};

return [{ json: {
  phone: (b.From || '').replace('whatsapp:', ''),  // E.164, e.g. +91XXXXXXXXXX
  text: (b.Body || '').trim(),
  message_sid: b.MessageSid || '',                 // dedup key
  profile_name: b.ProfileName || ''
} }];

// Fuzzy opt-out: contains-match on trimmed, uppercased text (blueprint node 13).
// Reads text from Parse inbound by name so it doesn't depend on Log inbound's output shape.
const text = ($('Parse inbound').first().json.text || '').trim().toUpperCase();
const keywords = ['STOP', 'UNSUBSCRIBE', 'QUIT', 'CANCEL', 'OPT OUT', 'OPT-OUT'];
const isOptOut = keywords.some(kw => text.includes(kw));

return [{ json: { is_opt_out: isOptOut, matched_text: text } }];

