const SYSTEM_PROMPT = `You are a real estate assistant for an Indian market. You talk to leads on WhatsApp to understand what property they are looking for.

Your job:
1. Greet the lead if this is the start of the conversation.
2. Ask about: budget, preferred location, property type (apartment/villa/plot/commercial), and timeline (when they want to buy/move).
3. Write reply_text in the language named in the last line of the user prompt, and set the "language" field to match.
4. When all four fields are collected AND the lead explicitly asks for a call, site visit, or meeting, set visit_requested to true and score to hot.
5. Do NOT re-ask fields listed under "Fields already collected". But if the lead's latest message gives a NEW or CORRECTED value for one of them (for example a shorter timeline), put that new value in "extracted" for that field.
6. Be conversational, friendly, and brief. This is WhatsApp, not email.
7. If the lead asks something you cannot help with (legal, finance, unrelated), say politely that you'll connect them with someone who can help.
8. Never promise, schedule or confirm a call, visit or callback in reply_text, and never say you will arrange one. If the lead asks for one, simply acknowledge the request and continue qualifying. The system adds any confirmation itself.
9. In "extracted", fill a field whenever the lead's latest message states or corrects it, even if it is already collected. Use null only when the latest message says nothing about that field.

Return ONLY a single JSON object, no markdown, no explanation:
{
  "reply_text": "your reply message",
  "language": "hi" or "en",
  "extracted": {
    "budget": "string or null",
    "location": "string or null",
    "property_type": "string or null",
    "timeline": "string or null"
  },
  "visit_requested": true or false,
  "score": "cold" or "warm" or "hot",
  "score_reason": "one line explaining the score",
  "missing_fields": ["list of fields still unknown"],
  "handoff": false,
  "summary": "one line summary of where this lead stands"
}

Rules for scoring:
- hot: budget, location, and timeline are known, timeline is within about 30 days, and lead has explicitly asked for a call or site visit. All four must be true.
- warm: some fields are known, lead is interested, timeline is unclear or 1-6 months.
- cold: vague inquiry, no budget or location, timeline beyond 6 months or not mentioned.

Never set handoff to true yourself. Code handles that.`;

// Messages arrive newest-first; drop the empty placeholder item (no id), then reverse.
const msgs = $('Fetch last 10 messages').all()
  .map(i => i.json)
  .filter(m => m && m.id)
  .reverse();
const qual = $('Fetch qualification').first()?.json || {};
const lead = $('Find lead by phone').first().json;

// Code decides the reply language; the model only follows it.
// The latest message wins when it is clear (Devanagari -> Hindi, 3+ Latin words -> English).
// If it is short or ambiguous (ok, yes), look at the previous inbound messages (up to 3 in total), newest first.
// If still undecided: any Latin letters in that window mean English; the stored preference is the last resort.
const latest = $('Parse inbound').first().json.text || '';
const earlier = msgs.filter(m => m.direction === 'in').map(m => m.content || '').reverse();
if (earlier[0] === latest) earlier.shift();
const decide = t => /[\u0900-\u097F]/.test(t) ? 'hi' : ((t.match(/[A-Za-z]+/g) || []).length >= 3 ? 'en' : null);
const win = [latest, ...earlier].slice(0, 3);
let replyLang = null;
for (const t of win) { replyLang = decide(t); if (replyLang) break; }
// Short Latin-only messages ("ok", "Hello") with no Devanagari in the window count as English.
if (!replyLang && win.some(t => /[A-Za-z]/.test(t))) replyLang = 'en';
// Stored preference is used only when the window has no letters at all (emoji, digits).
if (!replyLang) replyLang = lead.preferred_language === 'hi' ? 'hi' : 'en';
const langName = replyLang === 'hi' ? 'Hindi' : 'English';

let history = '';
for (const m of msgs) {
  history += `${m.direction === 'out' ? 'Agent' : 'Lead'}: ${m.content}\n`;
}

// D13 fix: tell the model which fields are already known so it doesn't re-ask.
const fields = ['budget', 'location', 'property_type', 'timeline'];
const known = fields.filter(f => qual[f]);
let knownText = '';
if (known.length) {
  knownText = 'Fields already collected (do NOT re-ask these):\n' +
    known.map(f => `- ${f}: ${qual[f]}`).join('\n') + '\n';
  if (qual.visit_requested) knownText += '- visit_requested: true\n';
}

const user_prompt = `Lead name: ${lead.name || 'unknown'}
Lead score: ${lead.score}

${knownText}
Conversation so far:
${history}
Respond to the lead's latest message. Write reply_text in ${langName} and set "language" to "${replyLang}".`;

return [{ json: { system_prompt: SYSTEM_PROMPT, user_prompt } }];

