// Response shape verified from a real run on 2026-10-21: choices[0].message.content (JSON string)
const res = $input.first().json;
const raw = res.choices?.[0]?.message?.content ?? '';
const qual = $('Fetch qualification').first()?.json || {};

const FIELDS = ['budget', 'location', 'property_type', 'timeline'];
const clean = v => {
  if (typeof v !== 'string') return null;
  const t = v.trim();
  return (!t || ['null', 'none', 'unknown', 'n/a'].includes(t.toLowerCase())) ? null : t;
};
const toAscii = s => s.replace(/[०-९]/g, d => String('०१२३४५६७८९'.indexOf(d)));

// Best-effort timeline -> days. Returns null if it can't be parsed (not a date calculation).
function timelineDays(text) {
  const m = toAscii(text.toLowerCase()).match(
    /(\d+)\s*(days?|din|दिन|weeks?|hafte|hafta|सप्ताह|हफ्ते|हफ़्ते|months?|mahine|mahina|महीने|महीना|महीन|years?|saal|sal|साल|वर्ष)/
  );
  if (!m) return null;
  const n = parseInt(m[1], 10);
  const u = m[2];
  let mult = null;
  if (/^(day|din|दिन)/.test(u)) mult = 1;
  else if (/^(week|haft|सप्ताह|हफ)/.test(u)) mult = 7;
  else if (/^(month|mahin|महीन)/.test(u)) mult = 30;
  else if (/^(year|saal|sal|साल|वर्ष)/.test(u)) mult = 365;
  return mult ? n * mult : null;
}

let ok = false, error = null, out = {};
try {
  const d = JSON.parse(raw);
  if (typeof d.reply_text !== 'string' || !d.reply_text.trim()) throw new Error('reply_text missing');
  if (!['cold', 'warm', 'hot'].includes(d.score)) throw new Error('bad score');
  if (!['hi', 'en'].includes(d.language)) throw new Error('bad language');
  if (!d.extracted || typeof d.extracted !== 'object') throw new Error('extracted missing');

  // Stored qualification + non-null values from this turn
  const merged = {};
  for (const f of FIELDS) merged[f] = clean(d.extracted[f]) ?? clean(qual[f]);
  const visit = d.visit_requested === true || qual.visit_requested === true;

  let score = d.score;
  let reason = d.score_reason || '';
  if (score === 'hot') {
    let why = null;
    if (!merged.budget || !merged.location || !merged.timeline) why = 'missing budget, location or timeline';
    else if (!visit) why = 'no explicit visit/call request';
    else {
      const days = timelineDays(merged.timeline);
      if (days !== null && days > 30) why = `timeline about ${days} days, over 30`;
    }
    if (why) { score = 'warm'; reason = `Downgraded by code (${why}). ` + reason; }
  }

  // Code adds the call confirmation only when the final (code-checked) score is hot.
  let reply = d.reply_text.trim();
  if (score === 'hot') {
    reply += d.language === 'hi'
      ? '\n\nहमारी टीम का एक सदस्य जल्द ही आपको कॉल करेगा।'
      : '\n\nA team member will call you shortly.';
  }

  out = {
    reply_text: reply,
    language: d.language,
    score,
    score_reason: reason,
    handoff: score === 'hot',          // code decides, never the model
    visit_requested: visit,
    summary: typeof d.summary === 'string' ? d.summary : '',
    missing_fields: Array.isArray(d.missing_fields) ? d.missing_fields : [],
    ...merged
  };
  ok = true;
} catch (e) {
  error = e.message;
}

return [{ json: { parse_ok: ok, error, raw, ...out } }];
